var raizCuadrada = (n, x1=1.1) => {
  if (n<0) throw "El número debe ser positivo";
  if (n===0 || n===1) return n;
  let x2;
  for(;;) {
    x2 =(x1+n/x1)/2 ;
    if (Math.abs(x1/x2-1)<1e-14) break ;
    x1 =x2 ;
  }
  return x2 ;
};

var raizCubica = function(n, x1=1.1) {
  if (n===0 || n===1) return n;
  let x2;
  do {
    x2 =(2*x1+n/x1**2)/3 ;
    if (Math.abs(x1/x2-1)<1e-11) return x2;
    x1 =x2 ;
  } while(true);
};

function raizCuarta(n, x1=1.1) {
  if (n<0) throw "El número debe ser positivo";
  if (n===0||n===1) return n;
  try {
    let x2;
    while(true) {
      x2 =(3*x1+n/x1**3)/4 ;
      if (Math.abs(x1/x2-1)<1e-10)throw x2 ;
      x1 =x2 ;
    }
  } catch(e) {
    return e ;
  }
};

var fibonacci = n => {
  if (n%1!==0) throw "El número debe ser entero";
  if (n<=0) throw "El número debe ser mayor a cero";
  if (n<3) return 1;
  try {
    let f3, f1=1, f2=1, i=3;
    for(;;) {
      f3 =f2+f1 ;
      if (i==n) throw f3;
      f1 =f2 ;
      f2 =f3 ;
      i++;
    }
  } catch(e) {
    return e;
  }
};

var chebyshev = (x, n) => {
  if (n%1!==0) throw "El orden debe ser entero";
  if (n<0) throw "El orden debe ser positivo";
  if (n===0) return 1;
  if (n===1) return x;
  try {
    let ch2, ch0=1, ch1=x, i=2;
    do {
      ch2 = 2*x*ch1-ch0;
      if (i===n)throw ch2;
      ch0 =ch1 ;
      ch1 =ch2 ;
      i++;
    } while(true);
  } catch(e) {
    return e;
  }
};

var legendre = function(x, n) {
  if (n%1!==0) throw "El orden debe ser entero";
  if (n<0) throw "El orden debe ser positivo";
  if (n===0) return 1;
  if (n===1) return x;
  let le2, le0=1, le1=x, i=2;
  for(;;) {
    le2 =(2-1/i)*x*le1-(1-1/i)*le0 ;
    if (i===n) break;
    le0 =le1 ;
    le1 =le2 ;
    i++;
  }
  return le2;
};

var laguerre = (x, n) => {
  if (n%1!==0) throw "El orden debe ser entero";
  if (n<0) throw "El orden debe ser positivo";
  if (n===0) return 1;
  if (n===1) return 1-x;
  try {
    let la2, la0=1, la1=1-x, i=2;
    for(;;) {
      la2 = ((2*i-1-x)*la1-(i-1)*la0)/i ;
      if (i===n)throw la2 ;
      la0 =la1 ;
      la1 =la2 ;
      i++;
    }
  } catch(e) {
    return e;
  }
};

function exponente(y) {
  if (y===0) return 1;
  const x =Math.abs(y) ;
  let s2, ter=1, s1=ter, i=1;
  while(true) {
    ter *= x/i ;
    s2 =s1+ter ;
    if (Math.abs(s1/s2-1)<1e-10) return y<0 ? 1/s2 : s2;
    s1 =s2 ;
    i++;
  }
};

var senoh = function(x) {
  if (x===0) return 0;
  try {
    const xx =x*x ;
    let s2, ter=x, s1=ter, i=2, j=3;
    while(true) {
      ter *=xx/(i*j) ;
      s2 =s1+ter ;
      if (Math.abs(s1/s2-1)<1e-10)throw s2 ;
      s1 =s2 ;
      i += 2;
      j += 2;
    }
  } catch(e) {
    return e ;
  }
};

var cosenoh = x => {
  if (x===0) return 1;
  const xx =x*x ;
  let s2, ter=1, s1=ter, i=1, j=2;
  for(;;) {
    ter *=xx/(i*j) ;
    s2 =s1+ter ;
    if (Math.abs(s1/s2-1)<1e-12) return s2;
    s1 =s2 ;
    i += 2;
