};

var atangenteh = function(x) {
  if (x===0) return 0;
  if (Math.abs(x)>=1) throw "El número debe ser menor a 1 (>=)";
  const xx =x*x ;
  let s2, ter=x, s1=ter, i=3;
  do {
    ter *=xx*(i-2)/i ;
    s2 =s1+ter ;
    if (Math.abs(s1/s2-1)<1e-15) break;
    s1 =s2 ;
    i += 2;
  } while(true);
  return s2 ;
};

var atangente = x => {
  if (x===0) return 0;
  if (Math.abs(x)>=1) throw "El número debe ser menor a 1 (>=)";
  try {
    const xx =-x*x ;
    let s2, ter=x, s1=ter, i=3;
    do {
      ter *= xx*(i-2)/i ;
      s2 = s1+ter;
      if (Math.abs(s1/s2-1)<1e-12)throw s2 ;
      s1 =s2 ;
      i +=2;
    } while(true);
  } catch(e) {
    return e ;
  }
};

var dobleSumatoria = function(n,m) {
  if (n===undefined) throw "Primer límite no definido";
  if (m===undefined) throw "Segundo límite no definido";
  if (n%1!==0 ||m%1!==0) throw "Los límites deben ser enteros";
  if (n<0 ||m<0) throw "Los límites deben ser positivos";
  let s1=0;
  for(let x=1;x<=n;x +=3) {
    let s2=0;
    for(let y=2;y<=m;y+=3)
      s2 += Math.sqrt(x**2+y**2);
    s1 +=s2;
  }
  return s1 ;
};

function prodSum(n,m) {
  if (n===undefined) throw "Primer límite no definido";
  if (m===undefined) throw "Segundo límite no definido";
  if (n%1!==0 || m%1!==0) throw "Los límites deben ser enteros";
  if (n<0 || m<0) throw "Los límites deben ser positivos";
  let p=1;
  for(let i=1; i<=n;i++) {
    let s=0;
    for(let j=2;j<=m;j+=2)
      s += (i+j)/2;
    p *=s;
  }
  return p;
};

var sumProd = function(n,m) {
  if (n===undefined) throw "Primer límite no definido";
  if (m===undefined) throw "Segundo límite no definido";
  if (n%1!==0 ||m%1!==0) throw "Los números deben ser enteros";
  if (n<0 || m<0) throw "Los números deben ser positivos";
  let s=0;
  for(let a=1;a<=n;a+=4) {
    let p=1;
    for(let b=2;b<=m;b+=3)
      p *=(a+b);
    s +=p;
  }
  return s ;
};
